<?php
declare(strict_types=1);

namespace StorvixLabs\CacheInsight\Model;

/**
 * What happened to a page request that was not answered from the cache, and how to read it.
 */
class Outcome
{
    public const HIT = 'hit';
    public const CACHEABLE_MISS = 'cacheable_miss';
    public const UNCACHEABLE_BLOCK = 'uncacheable_block';
    public const PRIVATE_RESPONSE = 'private_response';
    public const SESSION_COOKIE = 'session_cookie_set';
    public const REDIRECT = 'redirect';
    public const ERROR = 'error_response';

    /**
     * Classifies a response that was generated by PHP.
     *
     * With the built-in cache the browser always gets no-store headers and the stored copy has its cookies removed,
     * so only the layout decides; with Varnish or a CDN the response headers and cookies decide as well.
     *
     * @param string[] $setCookieNames
     */
    public static function classify(
        int $status,
        bool $layoutCacheable,
        string $cacheControl,
        array $setCookieNames,
        bool $sharedCache = true
    ): string {
        if (in_array($status, [301, 302, 303, 307, 308], true)) {
            return self::REDIRECT;
        }
        if ($status >= 400) {
            return self::ERROR;
        }
        if (!$layoutCacheable) {
            return self::UNCACHEABLE_BLOCK;
        }
        if (!$sharedCache) {
            return self::CACHEABLE_MISS;
        }
        if (preg_match('/\b(no-store|no-cache|private)\b/i', $cacheControl) === 1
            && stripos($cacheControl, 'public') === false
        ) {
            return self::PRIVATE_RESPONSE;
        }
        if (array_intersect(array_map('strtoupper', $setCookieNames), ['PHPSESSID'])) {
            return self::SESSION_COOKIE;
        }

        return self::CACHEABLE_MISS;
    }

    /**
     * @return array<string, array{label: string, advice: string}>
     */
    public static function describe(): array
    {
        return [
            self::CACHEABLE_MISS => [
                'label' => (string)__('Cacheable miss'),
                'advice' => (string)__('Page could be cached; it was cold or purged. Many of these means the cache is emptied too often (imports, indexers, cron, "flush cache" on deploys) or the lifetime is short. Warm it or purge less.'),
            ],
            self::UNCACHEABLE_BLOCK => [
                'label' => (string)__('Not cacheable: block'),
                'advice' => (string)__('A block with cacheable="false" in the layout turns the whole page uncacheable. See "Blocks that stop caching" below and load that content with JavaScript (customer sections) instead.'),
            ],
            self::PRIVATE_RESPONSE => [
                'label' => (string)__('Private response'),
                'advice' => (string)__('The response was marked private/no-store, usually by code that calls setNoCacheHeaders() or by a third-party module.'),
            ],
            self::SESSION_COOKIE => [
                'label' => (string)__('Session cookie set'),
                'advice' => (string)__('A cacheable page started a PHP session (PHPSESSID is set). Something on the page reads the session; with Varnish such responses are not cached.'),
            ],
            self::REDIRECT => [
                'label' => (string)__('Redirect'),
                'advice' => (string)__('Redirects are not cached by Magento. Many of them point at old URLs; fix the links or serve the redirect from the web server.'),
            ],
            self::ERROR => [
                'label' => (string)__('Error page (4xx/5xx)'),
                'advice' => (string)__('Not-found pages and errors. Many 404s mean bots or broken links hit PHP every time.'),
            ],
        ];
    }
}
